private static int dfs(int node, boolean[] hasApple, List<List<Integer>> graph) {
    if (node == -1) // Special case: direct parent node
        return 0;

    int result = 0; // Local result for this node
    for (int child : graph.get(node)) {
        if (dfs(child, hasApple, graph) > 0 || hasApple[child]) {
            result += 2; // Incorporate the cost of both steps and self
        }
    }

    return result;
}

public String sortString(String s) {
    StringBuilder sb = new StringBuilder();
    PriorityQueue<Character> minHeap = new PriorityQueue<>();
    PriorityQueue<Character> maxHeap = new PriorityQueue<>((a, b) -> Integer.compare(b, a));

    for (char c : s.toCharArray()) {
        minHeap.offer(c);
        maxHeap.offer(c);
    }

    while (!minHeap.isEmpty() || !maxHeap.isEmpty()) {
        if (!minHeap.isEmpty()) {
            char c = minHeap.poll();
            if (sb.length() == 0 || c < sb.charAt(sb.length() - 1)) {
                sb.append(c);
            } else {
                maxHeap.offer(c);
            }
        }
        if (!maxHeap.isEmpty()) {
            char c = maxHeap.poll();
            if (sb.length() == 0 || c > sb.charAt(sb.length() - 1)) {
                sb.append(c);
            } else {
                minHeap.offer(c);
            }
        }
    }

    return sb.toString();
}

