public String getSmallestString(int n, int k) {
    if (n == 1) {
        return Character.toString((char) (k + 'a' - 1));
    }

    StringBuilder result = new StringBuilder();
    int remainder = k % 26;
    int base = 1 + ((k - remainder) / 26);

    if (remainder == 0) {
        for (int i = base; i < n; i++) {
            result.append('z');
        }
        result.append((char) (base + remainder));
    } else {
        for (int i = base; i < n; i++) {
            result.append((char) (base + remainder));
        }
        result.append((char) (base + remainder - 1));
    }

    return result.toString();
}

