public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int m = mat.length, n = mat[0].length;
    int longest = 0;

    // Horizontal
    for (int i = 0; i < m; i++) {
        int count = 0;
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                count++;
                longest = Math.max(longest, count);
            } else {
                count = 0;
            }
        }
    }

    // Vertical
    for (int j = 0; j < n; j++) {
        int count = 0;
        for (int i = 0; i < m; i++) {
            if (mat[i][j] == 1) {
                count++;
                longest = Math.max(longest, count);
            } else {
                count = 0;
            }
        }
    }

    // Diagonal
    for (int i = 0; i < m; i++) {
        int count = 0;
        for (int j = 0; j < n; j++) {
            if (i == j && mat[i][j] == 1) {
                count++;
                longest = Math.max(longest, count);
            } else {
                count = 0;
            }
        }
    }

    // Anti-diagonal
    for (int i = m - 1; i >= 0; i--) {
        int count = 0;
        for (int j = 0; j < n; j++) {
            if (i + j == m - 1 && mat[i][j] == 1) {
                count++;
                longest = Math.max(longest, count);
            } else {
                count = 0;
            }
        }
    }

    return longest;
}

