public static int squarePermutations(int[] A) {
    int n = A.length;
    int[] visit = new int[101];

    int[] dp1 = new int[n]; // recurrence for non-ascending排列
    int[] dp2 = new int[n]; // recurrence for non-descending排列

    dp1[0] = 1;

    for (int i = 1; i < n; i++) {
        for (int j = 0; j <= A[i] - 2 * A[i - 1]; j++) {
            if (visit[A[i] - 2 * A[i - 1] + j + 1] != 1) dp1[i] = (dp1[i] + dp2[i - 1]) % 1000000007;
        }
        visit[A[i] - 2 * A[i - 1] + n - 1] = 1;
    }

    dp2[0] = 1;
    for (int i = 1; i < n; i++) {
        for (int j = A[i - 1] + 1; j < A[i] - 2 * A[i - 1]; j++) {
            if (visit[A[i] - 2 * A[i - 1] + 1 + j] != 1) dp2[i] = (dp2[i] + dp1[i - 1]) % 1000000007;
        }
        visit[A[i] - 2 * A[i - 1] + 0 - 1] = 1;
    }

    return (dp1[n - 1] + dp2[n - 1]) % 1000000007;
}

public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    int[] leftSmaller = new int[n];
    int[] rightSmaller = new int[n];
    int[] result = new int[n];

    // Calculate left smaller array
    for (int i = 0; i < n; i++) {
        int j = i - 1;
        while (j >= 0 && heights[j] >= heights[i]) {
            j = leftSmaller[j];
        }
        leftSmaller[i] = j;
    }

    // Calculate right smaller array
    for (int i = n - 1; i >= 0; i--) {
        int j = i + 1;
        while (j < n && heights[j] >= heights[i]) {
            j = rightSmaller[j];
        }
        rightSmaller[i] = j;
    }

    // Calculate maximum area
    for (int i = 0; i < n; i++) {
        result[i] = (rightSmaller[i] - leftSmaller[i] - 1) * heights[i];
    }

    int maxArea = 0;
    for (int i = 0; i < n; i++) {
        maxArea = Math.max(maxArea, result[i]);
    }

    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int currentRow = 0;
    int currentCol = 0;
    int isDescending = true;

    for (int i = 0; i < rows * cols; i++) {
        result[i] = mat[currentRow][currentCol];

        if (isDescending) {
            if (currentRow + 1 < rows && currentCol - 1 >= 0) {
                currentRow++;
                currentCol--;
            } else if (currentRow + 1 < rows) {
                currentRow++;
            } else {
                isDescending = false;
                currentCol++;
            }
        } else {
            if (currentRow - 1 >= 0 && currentCol + 1 < cols) {
                currentRow--;
                currentCol++;
            } else if (currentCol + 1 < cols) {
                currentCol++;
            } else {
                isDescending = true;
                currentRow--;
            }
        }
    }

    return result;
}

