        if (digits.get(i) < digits.get(i + 1)) {
            int temp = digits.get(i);
            digits.set(i, digits.get(i + 1));
            digits.set(i + 1, temp);
            break;
        }
    }

    long sum = 0;
    for (int d : digits) {
        sum = sum * 10 + d;
    }

    if (sum <= n) {
        return -1;
    }

    return (int) sum;
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n % 2 != 0) {
        result.add(String.valueOf(0));
    }
    for (int i = (n + 1) / 2; i < n; i++) {
        String prefix = "";
        for (int j = 1; j <= i; j++) {
            prefix += String.valueOf((j % 2 == 0) ? '0' : '9');
        }
        result.add(prefix + prefix);
    }
    return result;
}

public static boolean isBoomerang(int[][] points) {
    for (int i = 0; i < points.length - 1; i++) {
        int x = points[i][0];
        int y = points[i][1];
        int nextX = points[i + 1][0];
        int nextY = points[i + 1][1];
        if (x * (nextY - y) + y * (nextX - x) == 0) {
            return false;
        }
    }
    return true;
}

public static int findNthUglyNumber(int n) {
    int[] uglyNumbers = new int[n];
    int p2 = 0, p3 = 0, p5 = 0;
    uglyNumbers[0] = 1;
    for (int i = 1; i < n; i++) {
        int min = Math.min(uglyNumbers[p2] * 2, Math.min(uglyNumbers[p3] * 3, uglyNumbers[p5] * 5));
        uglyNumbers[i] = min;
        if (min == uglyNumbers[p2] * 2) {
            p2++;
        }
        if (min == uglyNumbers[p3] * 3) {
            p3++;
        }
        if (min == uglyNumbers[p5] * 5) {
            p5++;
        }
    }
    return uglyNumbers[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.length() == 0) {
        return 0;
    }

    int maxEnergy = 0;
    int currentEnergy = 1;
    char prevChar = s.charAt(0);

    for (int i = 1; i < s.length(); i++) {
        char currentChar = s.charAt(i);
        if (currentChar == prevChar) {
            currentEnergy++;
        } else {
            maxEnergy = Math.max(maxEnergy, currentEnergy);
            currentEnergy = 1;
        }
        prevChar = currentChar;
    }

    maxEnergy = Math.max(maxEnergy, currentEnergy);
    return maxEnergy;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) return result;

    dfs(result, 1, n);

    return result;
}

private static void dfs(List<Integer> result, int current, int n) {
    if (current > n) return;
    result.add(current);

    for (int i = 0; i <= 9; i++) {
        int next = current * 10 + i;
        dfs(result, next, n);
    }
}

public static int calculateUniqueSum(int[] nums) {
    Set<Integer> uniqueElements = new HashSet<>();
    int totalUniqueSum = 0;

    for (int num : nums) {
        if (!uniqueElements.contains(num)) {
            uniqueElements.add(num);
            totalUniqueSum += num;
        }
    }

    return totalUniqueSum;
}

public static int minPerfectSquareSum(int n) {
    int[] dp = new int[n + 1];
    Arrays.fill(dp, Integer.MAX_VALUE);
    dp[0] = 0;

    for (int i = 1; i <= n; i++) {
        int sqrt = (int) Math.sqrt(i);
        for (int j = 1; j <= sqrt; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    return dp[n];
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    for (int i = 0; i < words.length; i++) {
        words[i] = new StringBuilder(words[i]).reverse().toString();
    }
    return String.join(" ", words);
}
